+    let no_origin = align_roles(&w, &[(top, Role::Z), (front, Role::X)]).expect("two faces");
+    assert!(close(no_origin.pos, [10.0, 0.0, 10.0], 1e-9), "front face centroid, on the top plane: {:?}", no_origin.pos);
